package com.hospital.mes.reporting.application;

import com.hospital.mes.reporting.domain.PrintSourceConfiguration;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.springframework.stereotype.Component;
import org.springframework.jdbc.core.JdbcTemplate;
import com.hospital.mes.common.exception.ComplianceException;

/** Reviewed identifier/relationship registry. User configuration contains catalog identifiers only. */
@Component
public class PrintSourceCatalog {
 public static final String VERSION="printCatalog1";
 public record Field(String fieldId,String label,String dataType,String expression,String semantic){}
 public record Relation(String relationId,String parentCatalogId,String targetCatalogId,String cardinality,String parentFieldId,String targetFieldId){}
 public record Entity(String catalogId,String label,String table,String providerRef,String providerDataset,Map<String,Field> fields){}
 private final Map<String,PrintDataProvider> providers;private final Map<String,Entity> entities=new LinkedHashMap<>();private final Map<String,Relation> relations=new LinkedHashMap<>();private final JdbcTemplate jdbc;
 public PrintSourceCatalog(List<PrintDataProvider> registered,JdbcTemplate jdbc){this.jdbc=jdbc;var p=new LinkedHashMap<String,PrintDataProvider>();for(var provider:registered)p.put("provider."+provider.businessType(),provider);providers=Map.copyOf(p);
  physical("wms.receipt","收货单","wms_material_receipt",List.of(f("id","记录标识","TEXT"),f("receiptNo","收货单号","TEXT"),f("supplierId","供应商标识","TEXT"),f("receivedAt","收货日期","DATETIME"),f("recordStatus","单据状态","TEXT"),f("purchaseOrderNo","采购订单号","TEXT"),f("deliveryNoteNo","送货单号","TEXT"),f("versionNo","业务版本","TEXT")));
  var receiptFields=new ArrayList<>(List.of(f("id","记录标识","TEXT"),f("receiptId","收货单标识","TEXT"),f("materialId","物料标识","TEXT"),f("unitId","单据单位标识","TEXT"),f("receivedQty","实收数量","NUMBER"),f("lotNo","批号","TEXT"),f("supplierLotNo","供应商批号","TEXT"),f("packageSpec","包装规格","TEXT"),f("packageCount","包装件数","NUMBER"),f("expiryDate","有效期","DATE")));
  receiptFields.add(new Field("unit","单据单位（实时字典）","TEXT","(SELECT u.unit_name FROM md_unit u WHERE u.org_id=t.org_id AND u.id=t.unit_id)","LIVE_LOOKUP"));
  receiptFields.add(new Field("materialNameSnapshot","单据物料名称快照","TEXT","JSON_UNQUOTE(JSON_EXTRACT(t.material_snapshot_json,'$.materialName'))","BUSINESS_FROZEN"));physical("wms.receiptItem","收货明细","wms_material_receipt_item",receiptFields);
  physical("master.material","物料","md_material",List.of(f("id","记录标识","TEXT"),f("materialCode","物料编码","TEXT"),f("materialName","物料名称（当前）","TEXT")));
  physical("master.supplier","供应商","md_supplier",List.of(f("id","记录标识","TEXT"),f("supplierCode","供应商编码","TEXT"),f("supplierName","供应商名称（当前）","TEXT")));
  relation("receipt.items","wms.receipt","wms.receiptItem","1:N","id","receiptId");relation("receipt.supplier","wms.receipt","master.supplier","N:1","supplierId","id");relation("receiptItem.material","wms.receiptItem","master.material","N:1","materialId","id");
  for(var entry:providers.entrySet()){var provider=entry.getValue();var main=new LinkedHashMap<String,Field>();main.put("id",new Field("id","记录标识","TEXT",null,"NOT_APPLICABLE"));var items=new LinkedHashMap<String,Field>();
   for(var field:provider.fieldDefinitions()){var spec=new Field(field.key(),field.label(),field.dataType(),null,provider.businessType().equals("WMS_RECEIPT")&&field.key().equals("unit")?"LIVE_LOOKUP":"BUSINESS_FROZEN");(field.repeated()?items:main).put(field.key(),spec);}entities.put(entry.getKey(),new Entity(entry.getKey(),provider.documentLabel()+"（受控完整投影）",null,entry.getKey(),null,Map.copyOf(main)));
   var itemId=entry.getKey()+".items";entities.put(itemId,new Entity(itemId,provider.documentLabel()+"明细（受控投影）",null,entry.getKey(),"items",Map.copyOf(items)));relation(entry.getKey()+".itemsRelation",entry.getKey(),itemId,"1:N","id","id");
  }
 }
 private static Field f(String id,String label,String type){return new Field(id,label,type,"t."+id.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase(Locale.ROOT),type.equals("TEXT")?"CURRENT_REFERENCE":"BUSINESS_FROZEN");}
 private void physical(String id,String label,String table,List<Field> fields){var map=new LinkedHashMap<String,Field>();for(var f:fields)map.put(f.fieldId(),f);entities.put(id,new Entity(id,label,table,null,null,Map.copyOf(map)));}
 private void relation(String id,String parent,String target,String kind,String parentKey,String targetKey){relations.put(id,new Relation(id,parent,target,kind,parentKey,targetKey));}
 public Entity entity(String id){var e=entities.get(id);if(e==null)throw new IllegalArgumentException("Catalog unavailable: "+id);return e;}
 public PrintDataProvider policy(String ref){var p=providers.get(ref);if(p==null)throw new ComplianceException("PRINT_SOURCE_POLICY_INCOMPATIBLE","授权策略不可用");return p;}
 public boolean compatible(String policyRef,String catalog){var p=policy(policyRef);return catalog.equals(policyRef)||(p.businessType().equals("WMS_RECEIPT")&&catalog.equals("wms.receipt"));}
 public JsonNode policies(ObjectMapper json){var out=json.createArrayNode();providers.forEach((ref,p)->{var n=out.addObject();n.put("policyRef",ref).put("label",p.documentLabel()+"业务读取授权").put("policyVersion","1").put("enabled",true).put("description","每个真实记录由既有业务服务核对组织、当前读取权限和正式打印资格");var rights=n.putArray("businessReadPermissions");p.businessReadPermissions().forEach(rights::add);var catalogs=n.putArray("compatibleMainCatalogIds");catalogs.add(ref);if(p.businessType().equals("WMS_RECEIPT"))catalogs.add("wms.receipt");});return out;}
 public JsonNode metadata(ObjectMapper json){var out=json.createObjectNode();out.put("catalogVersion",VERSION);var limits=out.putObject("limits");limits.put("maxDepth",4).put("maxJoinNodes",12).put("maxFields",200).put("maxRowsPerDetail",2000).put("queryTimeoutSeconds",5);var list=out.putArray("entities");for(var e:entities.values()){var n=list.addObject();n.put("catalogId",e.catalogId()).put("label",e.label()).put("primaryKeyFieldId","id").put("organizationFilterApplied",true).put("softDeleteFilterApplied",false).put("configurable",true).putNull("unavailableReason");var fields=n.putArray("fields");e.fields().values().stream().sorted(Comparator.comparing(Field::fieldId)).forEach(f->{var v=fields.addObject();v.put("fieldId",f.fieldId()).put("label",f.label()).put("dataType",f.dataType()).put("nullable",true).put("snapshotSemantic",f.semantic()).put("sortable",e.table()!=null);if(f.dataType().equals("NUMBER"))v.put("precision",24).put("scale",6);else v.putNull("precision").putNull("scale");if(f.dataType().equals("DATETIME"))v.put("timezone","UTC");else v.putNull("timezone");});var rel=n.putArray("relations");relations.values().stream().filter(r->r.parentCatalogId().equals(e.catalogId())).forEach(r->{var v=rel.addObject();v.put("relationId",r.relationId()).put("parentCatalogId",r.parentCatalogId()).put("targetCatalogId",r.targetCatalogId()).put("cardinality",r.cardinality());v.putArray("keys").addObject().put("parentFieldId",r.parentFieldId()).put("targetFieldId",r.targetFieldId());});var policies=n.putArray("authorizationPolicyRefs");providers.keySet().stream().filter(p->compatible(p,e.catalogId())).forEach(policies::add);}return out;}
 public void verify(JsonNode config){var nodeCatalog=new HashMap<String,String>();nodeCatalog.put("main",config.path("mainCatalogId").asText());entity(nodeCatalog.get("main"));for(var j:config.path("joins"))nodeCatalog.put(j.path("nodeId").asText(),j.path("catalogId").asText());for(var j:config.path("joins")){var target=entity(j.path("catalogId").asText());var r=relations.get(j.path("knownRelationId").asText());if(r==null||!r.parentCatalogId().equals(nodeCatalog.get(j.path("parentNodeId").asText()))||!r.targetCatalogId().equals(target.catalogId())||!r.cardinality().equals(j.path("cardinality").asText())||j.path("keys").size()!=1||!j.path("keys").get(0).path("parentFieldId").asText().equals(r.parentFieldId())||!j.path("keys").get(0).path("targetFieldId").asText().equals(r.targetFieldId()))throw new IllegalArgumentException("Relation keys/cardinality are not registered");for(var sort:j.path("sort"))if(target.table()==null||!target.fields().containsKey(sort.path("catalogFieldId").asText()))throw new IllegalArgumentException("Sort field unavailable");}
  for(var f:config.path("fields")){var e=entity(nodeCatalog.get(f.path("sourcePath").path("nodeId").asText()));var catalogField=e.fields().get(f.path("sourcePath").path("catalogFieldId").asText());if(catalogField==null||!catalogField.dataType().equals(f.path("dataType").asText()))throw new IllegalArgumentException("Field catalog type mismatch");}
 }
 public JsonNode normalizeMetadata(String businessType,JsonNode request,ObjectMapper json){var ref=PrintSourceConfiguration.text(request,"authorizationPolicyRef",80);policy(ref);var allowed=request.path("compatibleMainCatalogIds");if(!allowed.isArray()||allowed.isEmpty()||allowed.size()>50)throw new IllegalArgumentException("Compatible catalogs required");var catalogs=new TreeSet<String>();for(var id:allowed){entity(id.asText());if(!compatible(ref,id.asText())||!catalogs.add(id.asText()))throw new IllegalArgumentException("Incompatible or duplicate catalog");}var result=json.createObjectNode();result.put("businessType",businessType).put("authorizationPolicyRef",ref);var ids=result.putArray("compatibleMainCatalogIds");catalogs.forEach(ids::add);var filters=request.path("fixedTypeFilters");if(!filters.isArray()||filters.size()>12)throw new IllegalArgumentException("Invalid fixed filters");var sorted=new ArrayList<JsonNode>();var keys=new HashSet<String>();for(var filter:filters){PrintSourceConfiguration.shape(filter,"catalogId","catalogFieldId","operator","value");var e=entity(PrintSourceConfiguration.text(filter,"catalogId",80));var field=e.fields().get(PrintSourceConfiguration.text(filter,"catalogFieldId",80));if(field==null||!filter.path("operator").asText().equals("EQ")||!keys.add(e.catalogId()+"/"+field.fieldId()))throw new IllegalArgumentException("Unknown or duplicate fixed filter");if(!filter.path("value").isNull())PrintSourceConfiguration.validateValue(field.dataType(),filter.path("value"));sorted.add(filter.deepCopy());}sorted.sort(Comparator.comparing((JsonNode f)->f.path("catalogId").asText()).thenComparing(f->f.path("catalogFieldId").asText()).thenComparing(f->PrintSourceConfiguration.canonical(f.path("value"),json)));var fa=result.putArray("fixedTypeFilters");sorted.forEach(fa::add);return result;}
 public List<Map<String,Object>> query(Entity e,long org,Map<String,Object> keys,JsonNode fixedFilters,JsonNode sort,long deadline){
  if(e.table()==null)throw new IllegalArgumentException("Projection catalog must use its registered provider");var select=new ArrayList<String>();e.fields().values().forEach(f->select.add(f.expression()+" AS `"+f.fieldId()+"`"));var where=new ArrayList<String>();var values=new ArrayList<Object>();where.add("t.org_id=?");values.add(org);for(var entry:keys.entrySet()){var field=e.fields().get(entry.getKey());if(field==null)throw new IllegalArgumentException("Unknown query key");if(entry.getValue()==null)return List.of();where.add(field.expression()+"=?");values.add(entry.getValue());}for(var filter:fixedFilters)if(filter.path("catalogId").asText().equals(e.catalogId())){var f=e.fields().get(filter.path("catalogFieldId").asText());if(f==null)throw new IllegalArgumentException("Unknown filter");if(filter.path("value").isNull())where.add(f.expression()+" IS NULL");else{where.add(f.expression()+"=?");values.add(filter.path("value").isBoolean()?filter.path("value").asBoolean():filter.path("value").asText());}}
  var order=new ArrayList<String>();for(var s:sort){var f=e.fields().get(s.path("catalogFieldId").asText());if(f==null||!Set.of("ASC","DESC").contains(s.path("direction").asText()))throw new IllegalArgumentException("Invalid ordering");order.add(f.expression()+" "+s.path("direction").asText());}order.add("t.id ASC");long remaining=deadline-System.nanoTime();if(remaining<=0)throw new ComplianceException("PRINT_SOURCE_LIMIT_EXCEEDED","取数超时");String sql="SELECT "+String.join(",",select)+" FROM "+e.table()+" t WHERE "+String.join(" AND ",where)+" ORDER BY "+String.join(",",order)+" LIMIT 2001";
  return jdbc.query(connection->{var statement=connection.prepareStatement(sql);statement.setQueryTimeout((int)Math.max(1,Math.ceil(remaining/1_000_000_000d)));for(int i=0;i<values.size();i++)statement.setObject(i+1,values.get(i));return statement;},(rs,row)->{var data=new LinkedHashMap<String,Object>();for(var f:e.fields().values())data.put(f.fieldId(),rs.getObject(f.fieldId()));return data;});
 }
 public boolean matches(Entity e,Map<String,Object> row,JsonNode filters){for(var f:filters)if(f.path("catalogId").asText().equals(e.catalogId())){Object v=row.get(f.path("catalogFieldId").asText());if(f.path("value").isNull()){if(v!=null)return false;}else if(!Objects.equals(Objects.toString(v,null),f.path("value").asText()))return false;}return true;}
}
